import React from 'react';
import './Adminmessages.css';  // CSS dosyasını doğru şekilde import ettik

function AdminMessages() {
    return (
        <>
        <Sidebar />
        <div className="messages-container">
            <h2>İletişim Mesajları</h2>
            
            {/* Mesaj 1 */}
            <div className="message-box">
                <h3>Mesaj Başlığı: Test</h3>
                <p>Mesaj İçeriği burada olacak.</p>
                <button className="respond-btn">Yanıtla</button>
            </div>

            {/* Mesaj 2 */}
            <div className="message-box">
                <h3>Mesaj Başlığı: Yardım Talebi</h3>
                <p>Mesaj İçeriği burada olacak.</p>
                <button className="respond-btn">Yanıtla</button>
            </div>

            {/* Diğer mesajlar buraya eklenebilir */}
        </div>
        </>
    );
}

export default AdminMessages;
